const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function log(msg: string) {
  process.stdout.write(`[${new Date().toISOString()}] ${msg}\n`);
}

/** Already generated and big enough? (makes relaunches idempotent) */
function isGood(name: string): boolean {
  const p = path.join(OUT_DIR, `${name}.jpg`);
  return existsSync(p) && statSync(p).size >= MIN_BYTES;
}

/** Run one child generation attempt. Resolves {ok, kb?, error?}. */
function runChild(job: Job, index: number): Promise<{ ok: boolean; kb?: number; error?: string }> {
  return new Promise((resolve) => {
    execFile(
      'bun',
      ['run', 'scripts/gen-one.ts', String(index)],
      { cwd: '/home/z/my-project', timeout: CHILD_TIMEOUT_MS, killSignal: 'SIGKILL', maxBuffer: 8 * 1024 * 1024 },
      (err, stdout, stderr) => {
        if (!err && isGood(job.name)) {
          const kb = Math.round(statSync(path.join(OUT_DIR, `${job.name}.jpg`)).size / 1024);
          resolve({ ok: true, kb });
          return;
        }
        const detail = (stderr || stdout || err?.message || 'unknown error').toString().trim().split('\n').slice(-3).join(' | ');
        resolve({ ok: false, error: detail.slice(0, 300) });
      }
    );
  });
}

/** Generate one image: 1 attempt + up to 2 retries, with 429-aware backoff. */
async function generateOne(job: Job, index: number): Promise<{ ok: boolean; kb?: number; error?: string }> {
  for (let attempt = 1; attempt <= 3; attempt++) {
    const r = await runChild(job, index);
    if (r.ok) return r;
    const rateLimited = /429|Too many requests/i.test(r.error || '');
    if (attempt < 3) {
      const wait = rateLimited ? 15_000 * attempt : 3_000 * attempt;
      log(`retry ${job.name}.jpg (attempt ${attempt}/3 failed: ${r.error}) — waiting ${Math.round(wait / 1000)}s`);
      await sleep(wait);
    } else {
      return { ok: false, error: r.error };
    }
  }
  return { ok: false, error: 'unreachable' };
}

/** Concurrency-limited promise pool. */
async function runPool(items: { job: Job; index: number }[], limit: number, worker: (it: { job: Job; index: number }) => Promise<void>) {
  let i = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) {
      const idx = i++;
      await worker(items[idx]);
    }
  });
  await Promise.all(runners);
}

async function main() {
  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync('/home/z/my-project/scripts/.jobs.json', JSON.stringify(jobs, null, 2));
  log(`=== SOVANN FARM image generation started: ${jobs.length} jobs, concurrency 3 (isolated child processes) ===`);

  let done = 0;
  const failed: Job[] = [];
  const all = jobs.map((job, index) => ({ job, index }));

  // ---- Pass 1: main run (skips files already generated by a previous run) ----
  await runPool(all, 3, async ({ job, index }) => {
    if (isGood(job.name)) {
      done++;
      log(`[${done}/${jobs.length}] skip ${job.name}.jpg (already exists)`);
      return;
    }
    await sleep((index % 3) * 2000); // slight stagger to soften rate limits
    const r = await generateOne(job, index);
    done++;
    if (r.ok) log(`[${done}/${jobs.length}] ok ${job.name}.jpg (${r.kb}KB)`);
    else {
      log(`[${done}/${jobs.length}] FAIL ${job.name}.jpg (${r.error})`);
      failed.push(job);
    }
  });
  log(`--- pass 1 complete: ${jobs.length - failed.length}/${jobs.length} ok, ${failed.length} failed ---`);

  // ---- Passes 2-3: verification re-attempts for missing/undersized files ----
  for (let pass = 2; pass <= 3 && failed.length > 0; pass++) {
    log(`--- verification pass ${pass}: re-attempting ${failed.length} file(s) ---`);
    const still: Job[] = [];
    await runPool(
      failed.map((job) => ({ job, index: jobs.indexOf(job) })),
      3,
      async ({ job, index }) => {
        if (isGood(job.name)) return;
        const r = await generateOne(job, index);
        if (r.ok) log(`[pass${pass}] ok ${job.name}.jpg (${r.kb}KB)`);
        else {
          log(`[pass${pass}] FAIL ${job.name}.jpg (${r.error})`);
          still.push(job);
        }
      }
    );
    failed.length = 0;
    failed.push(...still);
  }

  // ---- Final verification ----
  log('--- VERIFICATION ---');
  const problems: string[] = [];
  for (const job of jobs) {
    const p = path.join(OUT_DIR, `${job.name}.jpg`);
    if (!existsSync(p)) problems.push(`MISSING ${job.name}.jpg`);
    else {
      const bytes = statSync(p).size;
      if (bytes < MIN_BYTES) problems.push(`UNDERSIZED ${job.name}.jpg (${Math.round(bytes / 1024)}KB)`);
    }
  }
  log(`RESULT: ${jobs.length - problems.length}/${jobs.length} ok, ${problems.length} problem(s)`);
  for (const p of problems) log(p);
  log('=== DONE ===');
  process.exit(problems.length > 0 ? 2 : 0);
}

process.on('unhandledRejection', (e: any) => log(`ORCH_UNHANDLED: ${e?.message || e}`));
process.on('uncaughtException', (e: any) => log(`ORCH_UNCAUGHT: ${e?.message || e}`));

main().catch((e) => {
  log(`FATAL: ${e?.message || e}`);
  process.exit(1);
});
